// Fond 3D : un plan texturé avec l'image de fond, parenté à la caméra pour toujours
// remplir le cadre. Contrairement au fond CSS derrière le canvas, cette géométrie
// réelle peut être capturée et floutée par le disque "verre dépoli" du plateau.
const backdropDistance = 4000;
const backdropHeight = 2 * backdropDistance * Math.tan(camera.fov / 2);
const backdropWidth = backdropHeight * (engine.getRenderWidth() / engine.getRenderHeight());
const backdrop = BABYLON.MeshBuilder.CreatePlane("backdrop", { width: backdropWidth, height: backdropHeight }, scene);
backdrop.parent = camera;
backdrop.position = new BABYLON.Vector3(0, 0, backdropDistance);
backdrop.rotation.y = Math.PI;
backdrop.isPickable = false;
const backdropMat = new BABYLON.StandardMaterial("backdropMat", scene);
// Gris neutre uni adapté à une interface de slicer moderne (remplace l'ancien panorama photo).
backdropMat.emissiveColor = BABYLON.Color3.FromHexString("#2A2D33");
backdropMat.diffuseColor = BABYLON.Color3.Black();
backdropMat.specularColor = BABYLON.Color3.Black();
backdropMat.disableLighting = true;
backdropMat.backFaceCulling = false;
backdrop.material = backdropMat;

input.new_string:
// Fond 3D : une pièce close (boîte géante, faces intérieures visibles), fixe dans le monde
// (pas parentée à la caméra) pour que la grille peinte sur ses murs/sol/plafond affiche une
// vraie perspective en fonction de l'angle de vue, façon "chambre wireframe" infinie.
// Contrairement à l'ancien fond CSS derrière le canvas, cette géométrie réelle peut être
// capturée et floutée par le disque "verre dépoli" du plateau.
const backdropSize = 8000;
const backdropGridTex = new BABYLON.DynamicTexture("backdropGridTex", { width: 1024, height: 1024 }, scene, true);
{
  const ctx = backdropGridTex.getContext() as CanvasRenderingContext2D;
  const size = 1024;
  // Gris neutre uni adapté à une interface de slicer moderne (remplace l'ancien panorama photo).
  ctx.fillStyle = "#2A2D33";
  ctx.fillRect(0, 0, size, size);
  // Grille discrète : lignes fines et peu contrastées, la perspective réelle (murs/sol/
  // plafond de la boîte) fait le reste de l'effet visuel, pas la texture elle-même.
  ctx.strokeStyle = "rgba(255,255,255,0.05)";
  ctx.lineWidth = 2;
  const step = size / 16;
  for (let i = 0; i <= size; i += step) {
    ctx.beginPath(); ctx.moveTo(i, 0); ctx.lineTo(i, size); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(0, i); ctx.lineTo(size, i); ctx.stroke();
  }
  backdropGridTex.update(false);
}
backdropGridTex.wrapU = BABYLON.Texture.WRAP_ADDRESSMODE;
backdropGridTex.wrapV = BABYLON.Texture.WRAP_ADDRESSMODE;
backdropGridTex.uScale = backdropSize / 400;
backdropGridTex.vScale = backdropSize / 400;
const backdrop = BABYLON.MeshBuilder.CreateBox("backdrop", { size: backdropSize, sideOrientation: BABYLON.Mesh.BACKSIDE }, scene);
backdrop.position = new BABYLON.Vector3(0, backdropSize / 2 - HEIGHT, 0);
backdrop.isPickable = false;
const backdropMat = new BABYLON.StandardMaterial("backdropMat", scene);
backdropMat.emissiveTexture = backdropGridTex;
backdropMat.diffuseColor = BABYLON.Color3.Black();
backdropMat.specularColor = BABYLON.Color3.Black();
backdropMat.disableLighting = true;
backdropMat.backFaceCulling = false;
backdrop.material = backdropMat;

