.container {
  position: fixed;
  top: 20px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  z-index: 1000;
  pointer-events: none;
}

.toolbar {
  display: flex;
  align-items: center;
  pointer-events: auto;
  transition: background 0.3s cubic-bezier(0.4, 0, 0.2, 1), box-shadow 0.3s cubic-bezier(0.4, 0, 0.2, 1);

  background: rgba(255, 255, 255, 0.08);
  backdrop-filter: blur(3px);
  -webkit-backdrop-filter: blur(3px);
  border: none;
  box-shadow: 0 12px 40px 0 rgba(0, 0, 0, 0.35), 0 4px 16px 0 rgba(0, 0, 0, 0.25);
}

.topToolbar {
  padding: 8px 16px;
  border-radius: 33px;
  gap: 5.33px;
  position: relative;
  overflow: visible !important;
}

.bottomToolbar {
  padding: 6px 10px;
  border-radius: 22px;
  gap: 6px;
  overflow: visible !important;
}

