toolUseResult.originalFile:
$accent: #00f0ff;
$panel-bg: rgba(10, 15, 26, 0.3);
$panel-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.4), 0 2px 8px 0 rgba(0, 0, 0, 0.3);

.container {
  position: fixed;
  top: 96px;
  left: 24px;
  bottom: 96px;
  width: 268px;
  z-index: 100;
  display: flex;
  flex-direction: column;
  pointer-events: none;
}

.panel {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
  background: $panel-bg;
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
  border: none;
  border-radius: 18px;
  box-shadow: $panel-shadow;
  pointer-events: auto;
  overflow: hidden;
}

.header {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 14px 16px 10px;
  color: rgba(255, 255, 255, 0.9);
  font-family: 'Orbitron', sans-serif !important;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  flex-shrink: 0;
}

.headerIcon {
  color: $accent;
  filter: drop-shadow(0 0 6px rgba(0, 240, 255, 0.5));
}

.sectionLabel {
  padding: 10px 16px 6px;
  color: rgba(255, 255, 255, 0.4);
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  flex-shrink: 0;
}

/* ---- Barre d'outils CAD ---- */

.toolGrid {
  position: relative;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 4px;
  padding: 0 12px 8px;
  flex-shrink: 0;
}

.toolButton {
  position: relative;
  z-index: 2;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 4px;
  padding: 10px 4px;
  background: transparent;
  border: none;
  border-radius: 10px;
  color: rgba(255, 255, 255, 0.6);
  font-size: 9px;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s ease;
  outline: none;

  &:hover:not(:disabled) {
    color: white;
    background: rgba(255, 255, 255, 0.08);
  }

  &.active {
    color: $accent;
    background: rgba(0, 240, 255, 0.14);
    box-shadow: 0 0 12px rgba(0, 240, 255, 0.2);
  }

  &:disabled {
    opacity: 0.32;
    cursor: not-allowed;
  }
}

/* ---- Sélecteur de granularité de sélection ---- */

.segmented {
  position: relative;
  display: flex;
  margin: 0 12px 8px;
  padding: 4px;
  background: rgba(0, 0, 0, 0.25);
  border-radius: 12px;
  gap: 2px;
  flex-shrink: 0;
}

.activeIndicator {
  position: absolute;
  background: rgba(0, 240, 255, 0.18);
  box-shadow: 0 0 12px rgba(0, 240, 255, 0.25);
  border-radius: 9px;
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  pointer-events: none;
  z-index: 1;
  opacity: 0;
}

.segmentButton {
  position: relative;
  z-index: 2;
  flex: 1;
  padding: 6px 4px;
  background: transparent;
  border: none;
  border-radius: 9px;
  color: rgba(255, 255, 255, 0.6);
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  cursor: pointer;
  transition: color 0.2s ease;
  outline: none;

  &:hover:not(:disabled) { color: white; }
  &.active { color: $accent; }

  &:disabled {
    opacity: 0.32;
    cursor: not-allowed;
  }
}

/* ---- Arborescence ---- */

.treeScroll {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  overflow-x: hidden;
  padding: 0 8px 8px;

  &::-webkit-scrollbar { width: 4px; }
  &::-webkit-scrollbar-track { background: transparent; }
  &::-webkit-scrollbar-thumb {
    background: rgba(255, 255, 255, 0.15);
    border-radius: 2px;
  }
}

.treeList {
  list-style: none;
  margin: 0;
  padding: 0;
}

.treeNode { overflow: hidden; }

.treeRow {
  display: flex;
  align-items: center;
  gap: 6px;
  width: 100%;
  padding: 7px 8px;
  background: transparent;
  border: none;
  border-radius: 8px;
  color: rgba(255, 255, 255, 0.75);
  font-size: 11px;
  text-align: left;
  cursor: pointer;
  transition: all 0.15s ease;
  outline: none;

  &:hover { background: rgba(255, 255, 255, 0.07); color: white; }

  &.selected {
    background: rgba(0, 240, 255, 0.12);
    color: $accent;
  }

  &.suppressed {
    opacity: 0.4;
    text-decoration: line-through;
  }

  &.errored { color: #ff6b6b; }
}

.chevron {
  flex-shrink: 0;
  transition: transform 0.2s ease;
  color: rgba(255, 255, 255, 0.4);

  &.expanded { transform: rotate(90deg); }
}

.chevronSpacer {
  width: 12px;
  flex-shrink: 0;
}

.nodeIcon {
  flex-shrink: 0;
  color: rgba(0, 240, 255, 0.75);
}

.nodeName {
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.nodeAction {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  padding: 2px;
  background: transparent;
  border: none;
  border-radius: 4px;
  color: rgba(255, 255, 255, 0.35);
  cursor: pointer;
  opacity: 0;
  transition: all 0.15s ease;

  .treeRow:hover & { opacity: 1; }
  &:hover { color: white; background: rgba(255, 255, 255, 0.12); }
}

.childList {
  list-style: none;
  margin: 0;
  padding: 0 0 0 20px;
}

.childRow {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 5px 8px;
  color: rgba(255, 255, 255, 0.55);
  font-size: 10px;
}

.childDot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: rgba(0, 240, 255, 0.6);
  flex-shrink: 0;
}

.emptyState {
  padding: 24px 16px;
  text-align: center;
  color: rgba(255, 255, 255, 0.35);
  font-size: 10px;
  line-height: 1.6;
}

/* ---- Barre d'opérations : icônes seules, sous la barre d'onglets ---- */

.opsBar {
  position: fixed;
  // Pleine largeur + centrage par flex : un translateX(-50%) serait écrasé par la
  // transform que framer-motion pose pour animer `y`.
  //
  // La Sidebar est une pile verticale centrée à partir de top:20px — onglets (20→78px),
  // gap 10px, puis outils slicer (88→132px) — le tout en z-index 1000. En mode
  // modélisation la barre slicer se rétracte : on vient occuper exactement son
  // emplacement (88px) pour que l'échange se lise comme un morph d'une barre à l'autre.
  // z-index supérieur à la pile pour rester au-dessus pendant le croisement.
  top: 88px;
  left: 0;
  right: 0;
  z-index: 1001;
  display: flex;
  justify-content: center;
  pointer-events: none;
}

.opsBarInner {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 6px;
  background: $panel-bg;
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
  border: none;
  border-radius: 14px;
  box-shadow: $panel-shadow;
  pointer-events: auto;
}

// Petite barre secondaire des formes d'esquisse (Ligne, Rectangle, Cercle, Triangle,
// Courbe) : distincte de `.opsBar` plutôt qu'incluse dedans, positionnée juste en-dessous
// pour ne jamais élargir la barre principale — visible seulement quand l'outil Esquisse
// de `.opsBar` est actif.
.sketchBar {
  position: fixed;
  top: 144px;
  left: 0;
  right: 0;
  z-index: 1001;
  display: flex;
  justify-content: center;
  pointer-events: none;
}

.sketchBarInner {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 5px;
  background: $panel-bg;
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
  border: none;
  border-radius: 12px;
  box-shadow: $panel-shadow;
  pointer-events: auto;
}

.barButton {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 38px;
  height: 38px;
  background: transparent;
  border: none;
  border-radius: 10px;
  color: rgba(255, 255, 255, 0.65);
  cursor: pointer;
  transition: all 0.2s ease;
  outline: none;
  flex-shrink: 0;

  &:hover:not(:disabled) {
    color: white;
    background: rgba(255, 255, 255, 0.08);
  }

  &.active {
    color: $accent;
    background: rgba(0, 240, 255, 0.16);
    box-shadow: 0 0 12px rgba(0, 240, 255, 0.25);
  }

  &:disabled {
    opacity: 0.32;
    cursor: not-allowed;
  }
}

/* ---- Panneau de paramètres ---- */

.params {
  flex-shrink: 0;
  border-top: 1px solid rgba(255, 255, 255, 0.07);
  padding: 12px 16px 14px;
  background: rgba(0, 0, 0, 0.18);
}

.paramsTitle {
  color: $accent;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  margin-bottom: 10px;
}

.paramRow {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 8px;

  &:last-child { margin-bottom: 0; }
}

.paramLabel {
  color: rgba(255, 255, 255, 0.6);
  font-size: 10px;
  white-space: nowrap;
}

.paramInput {
  width: 88px;
  padding: 5px 8px;
  background: rgba(0, 0, 0, 0.35);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 6px;
  color: white;
  font-size: 10px;
  font-family: 'Orbitron', sans-serif !important;
  text-align: right;
  outline: none;
  transition: border-color 0.2s ease;

  &:focus { border-color: rgba(0, 240, 255, 0.6); }
}

.paramSelect {
  @extend .paramInput;
  text-align: left;
  cursor: pointer;

  option { background: #0a0f1a; }
}

.paramToggle {
  display: flex;
  align-items: center;
  gap: 6px;
  color: rgba(255, 255, 255, 0.6);
  font-size: 10px;
  cursor: pointer;

  input { accent-color: $accent; cursor: pointer; }
}

