.fusionMenuContainer {
  position: fixed;
  left: 200px;
  top: 76px;
  width: 195px;
  max-height: 400px;
  border: none;
  box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.4), 0 2px 8px 0 rgba(0, 0, 0, 0.3);
  border-radius: 16px;
  z-index: 1001;
  display: flex;
  flex-direction: column;
  overflow: visible;
  isolation: isolate;

  &::before {
    content: '';
    position: absolute;
    inset: 0;
    background: rgba(10, 15, 26, 0.25);
    backdrop-filter: blur(4px);
    -webkit-backdrop-filter: blur(4px);
    z-index: -1;
    border-radius: inherit;
    pointer-events: none;
  }
}

.tabButtonsContainer {
  display: flex;
  align-items: center;
  overflow: hidden;
  flex: 1;
  padding-right: 8px;
}

.activeTabTitle {
  font-family: 'Orbitron', sans-serif !important;
  font-size: 11px;
  font-weight: 700;
  color: #00f0ff;
  display: flex;
  align-items: center;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  width: 100%;
}

.fusionCloseBtn {
  background: transparent;
  border: none;
  color: rgba(255, 255, 255, 0.6);
  cursor: pointer;
  font-size: 14px;
  padding: 2px 4px;
  border-radius: 6px;
  transition: all 0.2s;
  flex-shrink: 0;

  &:hover {
    color: #fff;
    background: rgba(255, 255, 255, 0.1);
  }
}

.fusionMenuContent {
  padding: 12px;
  overflow-y: scroll;
  max-height: 400px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  border-radius: 16px;

  &::-webkit-scrollbar {
    width: 0px;
    background: transparent;
  }
}

.externalScrollThumb {
  position: absolute;
  left: calc(100% + 4px);
  width: 6px;
  background: rgba(255, 255, 255, 0.2);
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
  border-radius: 999px;
  pointer-events: auto;
  cursor: default;
  z-index: 1002;
  transition: width 0.25s cubic-bezier(0.16, 1, 0.3, 1), background 0.2s ease;

  &:hover, &.dragging {
    width: 12px;
    background: rgba(255, 255, 255, 0.35);
  }
}

.sectionGroup {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.sectionTitle {
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.45);
  letter-spacing: 0.5px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.itemsList {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.itemRow {
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.05);
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.35);
  padding: 8px 10px;
  border-radius: 8px;
  font-size: 11.5px;
  color: rgba(255, 255, 255, 0.9);
  cursor: pointer;
  transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);
  transform: perspective(400px) translateZ(0px);

  &:hover {
    background: rgba(255, 255, 255, 0.12);
    border-color: rgba(255, 255, 255, 0.2);
    color: #fff;
    transform: perspective(400px) translateZ(6px);
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
  }

  &.activeRow {
    background: rgba(0, 240, 255, 0.2);
    border-color: #00f0ff;
    color: #00f0ff;
    font-weight: 500;
  }
}

.itemName {
  font-weight: 600;
  font-size: 11.5px;
  color: #fff;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

