  }

  &.activePattern {
    background: rgba(0, 240, 255, 0.2);
    border-color: #00f0ff;
    color: #00f0ff;
    font-weight: 600;
  }
}

.tooltipContainer {
  position: fixed;
  z-index: 9999;
  pointer-events: none;
  background: rgba(10, 15, 26, 0.75);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  border: 1px solid rgba(0, 240, 255, 0.3);
  box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.5), 0 2px 8px 0 rgba(0, 0, 0, 0.3);
  padding: 10px 14px;
  border-radius: 16px;
  width: 240px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  animation: fadeIn 0.15s ease-out;
}

@keyframes fadeIn {
  from { opacity: 0; transform: scale(0.95); }
  to { opacity: 1; transform: scale(1); }
}

.header {
  display: flex;
  align-items: center;
  gap: 6px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
  padding-bottom: 4px;
}

.title {
  font-family: 'Orbitron', sans-serif !important;
  font-size: 12px;
  font-weight: 700;
  color: #00f0ff;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.body {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.divider {
  height: 1px;
  background: rgba(255, 255, 255, 0.1);
  margin: 3px 0;
}

.textureHeader {
  display: flex;
  align-items: center;
  gap: 5px;
  margin-bottom: 2px;
}

.subTitle {
  font-size: 11px;
  font-weight: 600;
  color: #fbbf24;
}

.row {
  display: flex;
  justify-content: space-between;
  font-size: 10.5px;
}

.label {
  color: rgba(255, 255, 255, 0.5);
  font-weight: 500;
}

.value {
  color: rgba(255, 255, 255, 0.9);
  font-weight: 600;
  text-align: right;
  max-width: 140px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.container {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  z-index: 1000;
  pointer-events: none;
}

.toolbar {
  display: flex;
  align-items: center;
  justify-content: center;
  pointer-events: auto;
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);

  background: rgba(10, 15, 26, 0.45);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  border: none;
  box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.4), 0 2px 8px 0 rgba(0, 0, 0, 0.3);
  padding: 10px 24px;
  border-radius: 20px;
  width: auto;
  max-width: 90vw;
  white-space: nowrap;
}

.secondaryToolbar {
  min-height: 44px;
}

.infoDisplayBottom {
  font-family: 'Oxanium', sans-serif !important;
  font-size: 13.5px;
  font-weight: 500;
  color: rgba(255, 255, 255, 0.9);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  text-align: center;
}

